package com.gameaggregator.tenantservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="member_roles",uniqueConstraints=@UniqueConstraint(columnNames={"member_id","role_id"})) public class MemberRole extends BaseEntity { @Column(name="member_id",nullable=false) private UUID memberId; @Column(name="role_id",nullable=false) private UUID roleId; protected MemberRole(){} public MemberRole(UUID memberId,UUID roleId){this.memberId=memberId;this.roleId=roleId;} public UUID getMemberId(){return memberId;} public UUID getRoleId(){return roleId;} }
